    out={}
    for x in atoms: out[x]=V(x)
    for c in consts: out[str(c)]=(lambda c:lambda B,W,a,f=0:c)(c)
    base=dict(out)
    for (n1,e1),(n2,e2) in itertools.product(base.items(),repeat=2):
        if n1<n2 or True:
            out[f'{n1}+{n2}']=(lambda e1,e2:lambda B,W,a,f=0:e1(B,W,a,f)+e2(B,W,a,f))(e1,e2)
            out[f'{n1}-{n2}']=(lambda e1,e2:lambda B,W,a,f=0:e1(B,W,a,f)-e2(B,W,a,f))(e1,e2)
    return out
E=exprs()
ops={'>':lambda x,y:x>y,'>=':lambda x,y:x>=y}
def preds(usef):
    for (ln,l),(rn,r) in itertools.product(E.items(),repeat=2):
        if not usef and ('f' in ln or 'f' in rn): continue
        for on,o in ops.items():
            yield f'{ln}{on}{rn}',(lambda l,r,o:lambda B,W,a,f=0:o(l(B,W,a,f),r(B,W,a,f)))(l,r,o)
corr_lim=lambda B,W,a:W+a>200
corr_fee=lambda B,W,a:5 if a>100 else 0
corr_fund=lambda B,W,a,f:a+f>B
def same(lim,feef,fund,Bs,Ws):
    bad=0
    for B in Bs:
        for W in Ws:
            for a in A:
                for d in (0,1):
                    if model(B,W,a,d,lim,feef,fund)!=model(B,W,a,d,corr_lim,corr_fee,corr_fund):
                        bad+=1
